import { db } from '../firebase/config';
import { collection, setDoc, getDoc, getDocs, updateDoc, deleteDoc, doc, query, where, serverTimestamp, Timestamp } from 'firebase/firestore';
import type { DocumentData } from 'firebase/firestore';
import type { Support_Session } from '../types/Support_Session';

// Collection: supportSessions. Document IDs are generated by Firestore and copied into sessID.
const COLLECTION = 'supportSessions';

// The type says sessDate is a Date, but Firestore always hands back a Timestamp, so convert on every read
const toSession = (data: DocumentData): Support_Session => ({
  ...(data as Support_Session),
  sessDate: data.sessDate instanceof Timestamp ? data.sessDate.toDate() : data.sessDate,
});

// ~~~~~~~~~~ CREATE ~~~~~~~~~~

// Returns the new sessID. sessTimestamp is set by the server.
export const createSupportSession = async (
  data: Omit<Support_Session, 'sessID' | 'sessTimestamp'>
): Promise<string> => {
  try {
    const ref = doc(collection(db, COLLECTION));
    await setDoc(ref, { ...data, sessID: ref.id, sessTimestamp: serverTimestamp() });
    return ref.id;
  } catch (error) {
    console.error('Error creating support session:', error);
    throw error;
  }
};

// ~~~~~~~~~~ READ ~~~~~~~~~~

// Get a session by sessID
export const getSupportSession = async (sessID: string): Promise<Support_Session | null> => {
  try {
    const snap = await getDoc(doc(db, COLLECTION, sessID));
    return snap.exists() ? toSession(snap.data()) : null;
  } catch (error) {
    console.error(`Error getting support session "${sessID}":`, error);
    throw error;
  }
};

// Get the session arranged from a request (one request becomes one session)
export const getSessionByRequest = async (reqID: string): Promise<Support_Session | null> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('reqID', '==', reqID)));
    return snap.empty ? null : toSession(snap.docs[0].data());
  } catch (error) {
    console.error(`Error getting session for request "${reqID}":`, error);
    throw error;
  }
};

// Get the sessions for a list of requests.
// A session has no student or volunteer ID of its own, so "my sessions" means: fetch my requests, then
// fetch the sessions for those requests. Firestore's "in" filter allows 30 values at most, hence the chunks.
export const getSessionsByRequestIDs = async (reqIDs: string[]): Promise<Support_Session[]> => {
  try {
    const chunks: string[][] = [];
    for (let i = 0; i < reqIDs.length; i += 30) chunks.push(reqIDs.slice(i, i + 30));

    const snaps = await Promise.all(
      chunks.map(chunk => getDocs(query(collection(db, COLLECTION), where('reqID', 'in', chunk))))
    );
    return snaps.flatMap(snap => snap.docs.map(d => toSession(d.data())));
  } catch (error) {
    console.error('Error getting sessions by request IDs:', error);
    throw error;
  }
};

// Get all sessions with a given status
export const getSessionsByStatus = async (sessStatus: Support_Session['sessStatus']): Promise<Support_Session[]> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('sessStatus', '==', sessStatus)));
    return snap.docs.map(d => toSession(d.data()));
  } catch (error) {
    console.error(`Error getting "${sessStatus}" sessions:`, error);
    throw error;
  }
};

// ~~~~~~~~~~ UPDATE ~~~~~~~~~~

export const updateSupportSession = async (
  sessID: string,
  updates: Partial<Omit<Support_Session, 'sessID'>>
): Promise<void> => {
  try {
    await updateDoc(doc(db, COLLECTION, sessID), { ...updates });
  } catch (error) {
    console.error(`Error updating support session "${sessID}":`, error);
    throw error;
  }
};

// Shortcut for status changes (Cancelled, Completed, Rated...)
export const updateSessionStatus = async (sessID: string, sessStatus: Support_Session['sessStatus']): Promise<void> => {
  try {
    await updateDoc(doc(db, COLLECTION, sessID), { sessStatus });
  } catch (error) {
    console.error(`Error setting session "${sessID}" to "${sessStatus}":`, error);
    throw error;
  }
};

// ~~~~~~~~~~ DELETE ~~~~~~~~~~

export const deleteSupportSession = async (sessID: string): Promise<void> => {
  try {
    await deleteDoc(doc(db, COLLECTION, sessID));
  } catch (error) {
    console.error(`Error deleting support session "${sessID}":`, error);
    throw error;
  }
};